'use strict';
const S={boot:null,view:'projects',projects:[],version:null,tab:'materials',questions:[],dirty:false,models:null,rubrics:{items:[]},run:null,selected:null,cropQuestion:0,cropFile:null,cropBooklet:null,cropPage:1,rect:null,image:null,normalization:null,pendingNormalization:null,reviewDrafts:new Map()};
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(text,action,extra='',primary=false)=>`<button type="button" data-action="${action}" ${extra} class="${primary?'primary':''}">${text}</button>`;
const option=(id,text,current)=>`<option value="${esc(id)}" ${id===current?'selected':''}>${esc(text)}</option>`;
const message=text=>{const el=$('#message');el.textContent=text;el.hidden=false;clearTimeout(message.timer);message.timer=setTimeout(()=>el.hidden=true,7000);};
function rememberRubricJob(job){try{sessionStorage.setItem('gscope-rubric-job',JSON.stringify({id:job.id,versionId:job.versionId}));}catch{}}
function forgetRubricJob(){try{sessionStorage.removeItem('gscope-rubric-job');}catch{}}
function recoverRubricJob(){try{const job=JSON.parse(sessionStorage.getItem('gscope-rubric-job')||'null');if(job&&typeof job.id==='string'&&/^[a-f0-9]{12,64}$/.test(job.id)&&typeof job.versionId==='string'&&/^[a-f0-9]{32}$/.test(job.versionId))S.normalization={id:job.id,versionId:job.versionId,recovered:true};}catch{}}
async function api(path,data){const r=await fetch(path,{method:data===undefined?'GET':'POST',headers:{'X-App-Token':S.boot?.token||'',...(data===undefined?{}:{'Content-Type':'application/json'})},...(data===undefined?{}:{body:JSON.stringify(data)}),cache:'no-store',credentials:'same-origin',redirect:'error'});const result=await r.json();if(typeof result.message==='string')result.message=assignmentLanguage(result.message);if(!r.ok)throw new Error(assignmentLanguage(result.error||'The local action could not finish.'));if(data!==undefined&&S.version)refreshAssignmentProgress(true);return result;}
async function leave({preserveGuidance=false}={}){if(window.GWorksDialogs.busy)return false;const dirty=window.GScopeAISettings?.dirty?.()||window.GScopeRosters?.dirty?.()||S.dirty||(!preserveGuidance&&window.GScopeConsistency?.dirty?.())||(window.GScopeMatching?.dirty?.()||window.GScopeMaterials?.dirty?.());if(!dirty)return true;if(!await confirmAction('Leave the unsaved edits?'))return false;S.dirty=false;window.GScopeAISettings?.discard?.();window.GScopeRosters?.discard?.();if(S.version)S.questions=structuredClone(S.version.questions);window.GScopeWorkflow?.discard?.();window.GScopeOutline?.discard?.();if(!preserveGuidance)window.GScopeConsistency?.discard?.();window.GScopeMaterials?.discard?.();window.GScopeMatching?.discard?.();window.GScopeGradeWorkspace?.discard?.();return true;}
function publish(requestId,type='navigation'){const origin=S.boot?.parentOrigin;if(origin&&parent!==window)parent.postMessage({source:'gwhiz-module',version:1,module:'grader',type,view:S.view,requestId},origin);}
function render(){
  window.GScopeTexEditors?.beforeRender?.();
  window.GScopeOutline?.capture?.();
  if(S.view==='rubrics'){S.view='projects';if(S.version)S.tab='rubric';}
  document.body.classList.toggle('embedded',!!S.boot?.parentOrigin&&parent!==window);
  $$('body>header [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===S.view));
  $('#app').innerHTML=S.view==='settings'?assignmentShell(settingsView(),'',null):S.view==='review'?assignmentShell(reviewView(),'reviewgrades',S.version,false):GScopeWorkflow.isIntake()?GScopeWorkflow.view():S.version?versionView():assignmentShell(projectsView(),'',null);
  if(S.view==='projects'&&S.version&&S.tab==='crops')loadPage().catch(e=>message(e.message));
  if(S.view==='review'&&S.run)bindReview();
  window.GScopeOutline?.mount?.();
  if(S.view==='projects'&&S.version&&S.tab==='roster')window.GScopeRosters?.mount?.(S.version.project_id).catch(e=>message(e.message));
  GScopeWorkflow.mount().catch(e=>message(e.message));
  if(S.view==='projects'&&S.version&&S.tab==='decisions')GScopeConsistency.mount().catch(e=>message(e.message));
  if(S.view==='projects'&&S.version&&['materials','rubric'].includes(S.tab))GScopeMaterials.mount().catch(e=>message(e.message));
  window.GScopeTexEditors?.mount?.(S.version?.id);
  window.GScopeGrading?.mount?.().catch(e=>message(e.message));window.GScopeGradeWorkspace?.mount?.().catch(e=>message(e.message));
  window.GScopeAISettings?.mount?.().catch(e=>message(e.message));
  if(['projects','review'].includes(S.view)&&S.version)refreshAssignmentProgress();
}
function projectOptions(){return S.projects.flatMap(p=>p.versions.map(v=>`<option value="${v.id}" ${S.version?.id===v.id?'selected':''}>${esc(p.course+' · '+termLabel(p.term)+' · '+p.title+' · '+v.label)}</option>`)).join('');}
const termLabel=value=>{const match=/^(fa|sp|su|wi)(\d{2})$/i.exec(value||'');return match?({fa:'Fall',sp:'Spring',su:'Summer',wi:'Winter'}[match[1].toLowerCase()]+' '+(2000+Number(match[2]))):String(value||'');};
function projectCourses(){const list=S.boot?.projectOptions?.courses||[{code:'135',defaultSemester:'fa26'},{code:'152',defaultSemester:'fa26'}];return [...new Map([...list,...S.projects.map(p=>({code:p.course}))].map(c=>[c.code,{...c,defaultSemester:c.defaultSemester||list.find(x=>x.code===c.code)?.defaultSemester}])).values()].sort((a,b)=>a.code.localeCompare(b.code,undefined,{numeric:true}));}
function projectTerms(){const lastYear=Math.min(2099,Math.max(2030,new Date().getFullYear()+3,...S.projects.map(p=>2000+Number(p.term.slice(2))).filter(Number.isFinite))),terms=['fa26'];for(let year=2027;year<=lastYear;year++)for(const season of ['sp','su','fa'])terms.push(season+String(year%100).padStart(2,'0'));return terms;}
function projectFormDraft(){const form=$('#new-project');if(form)S.projectDraft=Object.fromEntries(new FormData(form));}
// All modules use the desktop's single local dialog component.
const confirmAction=(text,options={})=>window.GWorksDialogs.confirm(text,options);
const promptAction=(text,defaultValue='',options={})=>window.GWorksDialogs.prompt(text,defaultValue,options);
// Fixed desktop actions expose navigation/dirty state, never records or paths.
window.GScopeDesktop={
 canClose:()=>!window.GWorksDialogs?.busy&&!S.dirty&&!S.reviewDrafts.size&&![window.GScopeAISettings,window.GScopeRosters,window.GScopeConsistency,window.GScopeMatching,window.GScopeMaterials].some(module=>module?.dirty?.()),
 requestClose:async()=>{if(S.reviewDrafts.size&&!await confirmAction('Close with unsaved grade reviews?'))return false;if(!await leave())return false;S.reviewDrafts.clear();return true;},
 requestRefresh:async()=>{if(S.reviewDrafts.size&&!await confirmAction('Refresh and discard unsaved grade reviews?'))return false;if(!await leave())return false;S.reviewDrafts.clear();return true;},
 refresh:async()=>{if(!await window.GScopeDesktop.requestRefresh())return false;location.reload();return true;},
 back:async()=>{if(!await leave())return false;S.view='projects';S.version=null;S.questions=[];S.run=null;render();publish();return true;},
 forward:()=>false,
 preview:async()=>{if(!S.version||!await leave())return false;S.view='projects';S.tab='template';render();publish();return true;},
 settings:async()=>{if(window.pywebview?.api?.open_settings)return window.pywebview.api.open_settings();message('Open Settings from the G-Scope desktop app.');return false;}
};
document.addEventListener('keydown',event=>{if(event.key==='F5'||((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='r')){event.preventDefault();window.GScopeDesktop.refresh().catch(error=>message(error.message));}},true);
function confirmProjectAction(title,text,confirmLabel){return confirmAction(text,{title,confirmLabel});}

function projectsView(){const courses=projectCourses(),draft=S.projectDraft||{},course=draft.course||courses.find(c=>c.code==='135')?.code||courses[0]?.code,preferredTerm=draft.term||courses.find(c=>c.code===course)?.defaultSemester,term=projectTerms().includes(preferredTerm)?preferredTerm:'fa26';return `${S.projectActionStatus?`<p class="notice project-action-status" role="status">${esc(S.projectActionStatus)}</p>`:""}<div class="project-workspace"><section class="card"><h2>New assignment</h2><p class="help">One assignment per course, semester and exam. Choose how many versions you expect; add more later.</p><form id="new-project" class="project-form"><label>Course<select name="course" required>${courses.map(c=>option(c.code,'Math '+c.code,course)).join('')}</select></label><label>Semester<select name="term" required>${projectTerms().map(t=>option(t,termLabel(t),term)).join('')}</select></label><label>Exam title<select name="title" required>${['Exam 1','Exam 2','Exam 3','Final Exam'].map(t=>option(t,t,draft.title||'Exam 1')).join('')}</select></label><label class="project-version-count">Versions<input type="number" name="versionCount" min="1" max="26" step="1" value="${esc(draft.versionCount||1)}" required aria-label="Number of exam versions"></label><button class="primary">+ Create assignment</button></form></section><section><h2>Saved assignments</h2>${S.projects.length?S.projects.map(p=>`<section class="card"><h3>Math ${esc(p.course)} · ${esc(termLabel(p.term))} · ${esc(p.title)}</h3><div class="row">${button('Open assignment','view-project',`data-id="${p.id}"`)}<span class="help">Versions ${p.versions.map(v=>esc(v.label)).join(', ')}</span>${button('+ Add version','add-version',`data-id="${p.id}"`)}${button('Delete assignment','delete-project',`data-id="${p.id}"`)}</div><details class="project-version-manager"><summary>Manage versions</summary>${p.versions.map(v=>`<div class="row"><strong>Version ${esc(v.label)}</strong>${button('Remove unused version','remove-version',`data-id="${v.id}" data-label="${esc(v.label)}"`)}</div>`).join('')}${(p.removedVersions||[]).map(v=>`<div class="row"><span>Removed Version ${esc(v.label)}</span>${button('Restore','restore-version',`data-id="${v.id}"`)}</div>`).join('')}</details></section>`).join(''):'<section class="card"><p>No assignments yet.</p></section>'}</section></div>${S.projectTrash?.length||S.projectTrashCleanup?.pendingProjects?`<details class="card project-trash" ${S.trashOpen?"open":""}><summary>Assignment Trash (${S.projectTrash?.length||0})</summary><div class="project-trash-toolbar"><p class="help">Deleted assignments and their files stay local for recovery. Restore an assignment to use it again.</p>${button(S.projectActionBusy?"Working…":"Clear trash","clear-project-trash",S.projectActionBusy||!S.boot?.projectTrashClear?'disabled title="Reopen G-Scope to load Clear trash"':'')}</div>${S.projectTrashCleanup?.pendingProjects?`<p class="notice warning">${S.projectTrashCleanup.pendingProjects} cleared assignment(s) still have local files awaiting cleanup. Close previews, check folder access and retry Clear trash.</p>`:""}${(S.projectTrash||[]).map(p=>`<div class="scan-row"><strong>Math ${esc(p.course)} · ${esc(termLabel(p.term))} · ${esc(p.title)}</strong> ${button('Restore assignment','restore-project',`data-id="${p.id}"`)}</div>`).join('')}</details>`:''}<p class="help">Scans, rubrics and proposals are stored in the private local G-Scope database. They are never included in app updates or shared installation packages.</p>`;}
const wizardSteps=[['materials','Exam source'],['template','Exam outline'],['rubric','Rubrics & answer keys'],['decisions','Grading guidance · Optional'],['roster','Exam roster'],['scans','Exam scans'],['match','Student matching'],['process','Grade submissions'],['reviewgrades','Review grades']];
const assignmentProgressCache=new Map();
function assignmentLanguage(text){return String(text||'').replace(/\bexam projects\b/gi,'assignments').replace(/\bexam project\b/gi,'assignment').replace(/(?<![\/\\])\bprojects\b/gi,word=>word[0]==='P'?'Assignments':'assignments').replace(/(?<![\/\\])\bproject\b/gi,word=>word[0]==='P'?'Assignment':'assignment');}
function assignmentStep(data,id){const p=data?.steps?.[id],state=p?.state||'empty',label=!p?'Saved progress not checked yet':state==='done'?'Complete':state==='partial'?'Partially complete':'Not started';return {state,label,title:label+(p?' · '+p.complete+' / '+p.total+(id==='roster'?' roster':' versions'):'')};}
function assignmentNavigation(v,active){
 const data=v?assignmentProgressCache.get(v.project_id)?.data:null;
 return '<button type="button" data-action="projects" class="g2-nav-home '+(!v?'active':'')+'" '+(!v?'aria-current="page"':'')+'><span aria-hidden="true">☷</span><span>Assignments</span></button>'+(v?'<div class="g2-assignment-name"><strong>'+esc(v.project.title)+'</strong><span>Math '+esc(v.project.course)+' · '+esc(termLabel(v.project.term))+'</span></div>'+wizardSteps.map(([id,title])=>{
  const {state:status,label,title:detail}=assignmentStep(data,id);
  return '<button data-action="tab" data-tab="'+id+'" class="'+(active===id?'active':'')+'" '+(active===id?'aria-current="step"':'')+' title="'+esc(detail)+'"><span class="g2-step-marker" data-progress="'+status+'" aria-label="'+label+'">'+(status==='done'?'✓':'')+'</span><span>'+esc(id==='decisions'?'Grading guidance':title)+(id==='decisions'?'<small>Optional</small>':'')+'</span></button>';
 }).join(''):'');
}
function assignmentSidebar(v,active){return '<aside class="g2-workflow-sidebar" aria-label="Assignment navigation"><nav aria-label="'+(v?'Assignment workflow':'Assignments')+'">'+assignmentNavigation(v,active)+'</nav></aside>';}
async function refreshAssignmentProgress(force=false){
 const v=S.version;if(!v)return;const pid=v.project_id;let item=assignmentProgressCache.get(pid);
 if(!item){item={data:null,loading:false,updated:0,again:false};assignmentProgressCache.set(pid,item);}
 if(item.loading){if(force)item.again=true;return;}if(!force&&Date.now()-item.updated<10000)return;item.loading=true;
 try{item.data=await api('/api/projects/'+pid+'/workflow-status');if(S.version?.project_id===pid&&['projects','review'].includes(S.view)){const nav=$('.g2-workflow-sidebar nav');if(nav)for(const button of nav.querySelectorAll('[data-tab]')){const info=assignmentStep(item.data,button.dataset.tab),marker=button.querySelector('.g2-step-marker');button.title=info.title;if(marker){marker.dataset.progress=info.state;marker.setAttribute('aria-label',info.label);marker.textContent=info.state==='done'?'✓':'';}}}}
 catch{}finally{item.loading=false;item.updated=Date.now();if(item.again){item.again=false;refreshAssignmentProgress(true);}}
}
function assignmentShell(content,active=S.tab,version=S.version,controls=true){const v=version;return `<div class="g2-assignment-shell">${assignmentSidebar(v,active)}<section class="g2-assignment-main">${v&&controls?`<div class="g2-version-bar"><strong>${esc(wizardSteps.find(x=>x[0]===active)?.[1]||'Question crops')}</strong>${['materials','roster','scans','match'].includes(active)?'<span class="pill">All versions</span>':`<div class="gs-top-version-controls"><div class="gs-version-buttons" role="group" aria-label="Exam version">${(S.projects.find(x=>x.id===v.project_id)?.versions||[{id:v.id,label:v.label}]).map(x=>`<button data-action="project-version" data-id="${x.id}" aria-pressed="${x.id===v.id}" ${x.id===v.id?'aria-current="true"':''}><strong>Version ${esc(x.label)}</strong><small>${v.project.examCounts?.[x.id]??x.examCount??0} exams</small></button>`).join('')}</div>${active==='template'?button('Copy outline to…','outline-copy-open'):''}</div>`}</div>`:""}${window.GScopeMatching?.backgroundView?.()||''}<div class="g2-step-content">${content}</div></section></div>`;}
function versionView(){return assignmentShell(({roster:()=>GScopeRosters.view(S.version.project_id),scans:scansView,materials:GScopeMaterials.view,rubric:rubricView,template:()=>'<div class="exam-outline-workspace">'+GScopeWorkflow.templateView()+GScopeOutline.view()+'</div>',match:()=>GScopeWorkflow.stageView('match'),crops:cropsView,decisions:()=>GScopeConsistency.view()+legacyGuidanceView(),process:processView,reviewgrades:()=>GScopeGrading.reviewSummary(S.version)})[S.tab]());}
function reviewView(){return S.version?assignmentShell(runReviewView(),'reviewgrades'):runReviewView();}


function scansView(){return GScopeWorkflow.stageView('scans');}
function rubricMethod(){S.rubricMethods||={};const v=S.version;return S.rubricMethods[v.id]||(v.libraryRubric?'saved':v.raw_rubric?.trim()?'import':S.questions.some(q=>q.items.length)?'manual':'saved');}
function questionSetupStep(){S.questionSetupSteps||={};return S.questionSetupSteps[S.version.id]||'answers';}
const SOLUTION_BLOCK=/\s*\[G-Scope reviewed solution; version ([^\]]+)\]\n([\s\S]*?)\n\[\/G-Scope reviewed solution\]/g;
function reviewedSolution(q){const match=[...(q.guidance||'').matchAll(SOLUTION_BLOCK)].find(m=>m[1]===String(S.version.label).replace(/^version\s+/i,''));return match?.[2]||'';}
function gradingNotes(q){return (q.guidance||'').replace(SOLUTION_BLOCK,'').trim();}
function withNotes(q,text){const blocks=(q.guidance||'').match(SOLUTION_BLOCK)||[];return String(text).trim()+(blocks.length?'\n'+blocks.join('\n').trim():'');}
function legacyGuidanceView(){const notes=S.questions.filter(q=>gradingNotes(q));return notes.length?'<section class="card"><details><summary>Existing question notes</summary>'+notes.map(q=>'<p><strong>Question '+esc(q.key)+'</strong></p><p>'+esc(gradingNotes(q))+'</p>').join('')+'</details></section>':'';}
function gradingNotesView(){return `<section class="card grading-notes-panel"><div class="spread"><h2>Grading guidance <span class="help">Optional</span></h2>${button('Skip guidance → Exam roster','tab','data-tab="roster"')}</div><p class="help">Add notes about common mistakes or how to assess work. The reviewed answer and rubric remain separate.</p>${S.questions.map(q=>`<article class="grading-notes-question"><label for="guidance-${esc(q.id||q.key)}">Question ${esc(q.key)}</label><textarea id="guidance-${esc(q.id||q.key)}" data-guidance-question="${esc(q.key)}" rows="3" maxlength="4000" placeholder="Common mistakes, reasoning to look for, or a grading note…">${esc(gradingNotes(q))}</textarea></article>`).join('')}<div class="row">${button('Save grading guidance','save-questions','',true)}${button('← Review rubric','question-setup-step','data-step="rubric"')}</div><p class="help">Changing an answer, rubric or guidance requires fresh rubric confirmation and a new grading run.</p></section>`;}
function rubricView(){
  const v=S.version,method=rubricMethod(),working=!!S.normalization,hasItems=S.questions.some(q=>q.items.length),editing=method==='manual'||hasItems,layout=S.rubricLayout||'grid',confirmed=!!v.rubric_approved&&!S.dirty,structured=!!v.rubricStructured;
  const step=questionSetupStep(),answerCount=v.questions.filter(q=>reviewedSolution(q)).length,answersDone=!!v.questions.length&&answerCount===v.questions.length;
  return `<section class="card question-setup-workflow"><h2>Set up each question · Version ${esc(v.label)}</h2><nav class="question-setup-steps" aria-label="Question setup steps">${[['answers','1 · Answer keys',answersDone,answerCount+'/'+v.questions.length+' reviewed'],['rubric','2 · Rubrics',confirmed,confirmed?'Confirmed':'Needs review']].map(([key,title,done,status])=>button((done?'✓ ':'')+title+'<small>'+status+'</small>','question-setup-step',`data-step="${key}" data-complete="${done}" ${step===key?'aria-current="step"':''}`)).join('')}</nav></section><div data-setup-panel="answers" ${step==='answers'?'':'hidden'}>${GScopeMaterials.answerView()}<div class="row question-setup-navigation">${button('Continue to rubrics →','question-setup-step','data-step="rubric"')}</div></div><div data-setup-panel="rubric" ${step==='rubric'?'':'hidden'}><section class="card rubric-method-card"><h2>How would you like to set up the rubric?</h2><div class="rubric-method-choices" role="group" aria-label="Rubric setup method">${[['saved','Saved G-Rater export'],['import','Upload or paste a rubric'],['ai','Generate with local AI'],['manual','Write it myself']].map(([id,title])=>button(title,'rubric-method',`data-method="${id}" aria-pressed="${method===id}"`)).join('')}</div><p class="help">Choose one starting method. You can edit the resulting rubric items below.</p>
  <div class="rubric-method-panel" data-rubric-method="saved" ${method==='saved'?'':'hidden'}><h3>Choose a saved G-Rater export</h3><p class="help">Click Refresh to pick up G-Rater exports from Downloads/G-Rater/Rubrics. Valid exports are copied into G-Scope’s Rubric Folder; no AI or pairing is needed. Use the folder button to manage those copies. If Chrome uses a custom download folder, upload the saved file instead.</p><label>Saved rubric<select id="saved-rubric"><option value="">Choose a saved rubric</option>${S.rubrics.items.map(r=>option(r.id,r.title+(r.structured?' · Structured items':r.prepared?' · Reviewed items':''),v.libraryRubric?.rubric_id)).join('')}</select></label><div class="row">${button('Load saved rubric','library-load',working?'disabled':'',true)}${button('Refresh','library-refresh')}${button('Open Rubric Folder','rubric-folder')}</div><p class="help">${structured?'This structured rubric is ready in the question editors below. Check its boxes, points and selection rules, then confirm the complete rubric.':'Text-only exports need Organize rubric text. Structured exports and saved reviewed items load directly; no AI transcription is needed.'}</p>${structured?'':button('Organize rubric text','normalize-rubric',working?'disabled':'')}</div>
  <div class="rubric-method-panel" data-rubric-method="import" ${method==='import'?'':'hidden'}><h3>Upload or paste a rubric</h3><label>G-Rater JSON<input type="file" accept="application/json,.json" id="rubric-file" ${working?'disabled':''}></label><details class="rubric-text-details"><summary>View or paste rubric text</summary><label>Rubric text<textarea id="raw-rubric" rows="5">${esc(v.raw_rubric)}</textarea></label>${button('Save rubric text','save-raw')}</details><div class="row">${structured?'':button('Organize rubric text','normalize-rubric',working?'disabled':'',true)}</div><p class="help">Structured JSON loads editable items directly. Older text-only exports can be organized with local AI. Review the result against your source.</p></div>
  <div class="rubric-method-panel" data-rubric-method="ai" ${method==='ai'?'':'hidden'}><h3>Generate a draft from the blank exam</h3><p class="help">Local AI proposes new grading criteria. Save the outline boxes and point values first; review every proposed item before confirming. Student scans are not used for this step.</p><p class="help">${esc(S.boot?.generalAI?.label||'General AI · configured in Settings → AI')}</p>${button('Generate draft rubric','generate-rubric',working?'disabled':'',true)}</div>
  <div class="rubric-method-panel" data-rubric-method="manual" ${method==='manual'?'':'hidden'}><h3>Write your rubric</h3><p class="help">Add criteria and signed point values for each outlined question below. Switch between Grid and List to arrange the same rubric items.</p></div>
  <div class="rubric-job-status" ${working||S.pendingNormalization?.versionId===v.id?'':'hidden'}><p id="normalization-status" class="help" aria-live="polite">${working?'The local model is preparing rubric proposals…':''}</p>${working?button('Stop rubric preparation','cancel-normalization'):''}${S.pendingNormalization?.versionId===v.id?button('Load proposed cards','load-normalization','',true):''}</div></section>
  <div id="rubric-editor" ${editing?'':'hidden'}><section class="card rubric-review-actions"><h2>Save rubrics</h2><div class="row">${button(S.savingRubric?'Saving…':'Save and apply to all versions','approve-share-rubric',S.savingRubric?'disabled':'',true)}${button('Save this version','approve-rubric',S.savingRubric?'disabled':'')}${button('Save to rubric library','library-save-version',confirmed?'':'disabled')}${button('Add question','add-question')}</div><p class="help">Saving applies the rubric and response format to all chosen versions. Correct answers, expected work and question boxes stay version-specific. Finish missing answer-key settings before grading. Library saves are reusable in other assignments.</p></section><section class="card rubric-editor-toolbar"><div><h2>Question rubrics</h2><p class="help">Check descriptions, points and selection rules before confirming.</p></div><div class="rubric-layout-switch" role="group" aria-label="Rubric display">${button('Grid','rubric-layout',`data-layout="grid" aria-pressed="${layout==='grid'}"`)}${button('List','rubric-layout',`data-layout="list" aria-pressed="${layout==='list'}"`)}</div></section><div id="questions" class="rubric-questions rubric-layout-${layout}">${rubricQuestionCards()}</div></div><div class="row question-setup-navigation">${button('← Answer keys','question-setup-step','data-step="answers"')}${button('Grading guidance (optional) →','tab','data-tab="decisions"')}${button('Continue to exam roster →','tab','data-tab="roster"')}</div></div>`;
}
function rubricQuestionCards(){
  const outline=S.version.rubricOutline||[],byKey=new Map(S.questions.map((q,i)=>[q.key,{q,i}])),seen=new Set();
  if(!outline.length)return S.questions.map((q,i)=>questionEditor(q,i)).join('');
  let html='';
  for(const node of outline){if(!node.graded){html+=`<div class="card rubric-outline-parent"><strong>Question ${esc(node.key)} · ${node.maxPoints} points across its parts</strong></div>`;continue;}
    const item=byKey.get(node.key);if(item){html+=questionEditor(item.q,item.i);seen.add(node.key);}}
  return html+S.questions.filter(q=>!seen.has(q.key)).map(q=>questionEditor(q,S.questions.indexOf(q))).join('');
}
function questionEditor(q,index){
  const preview=q.id&&q.rect&&S.version.files.some(f=>f.kind==='handout');
  return `<section class="card question rubric-question" data-index="${index}"><header class="rubric-question-heading"><h3>Question ${esc(q.key)}${q.title&&q.title!==q.key?' · '+esc(q.title):''}</h3><span class="pill">${q.maxPoints} points</span></header><div class="rubric-question-body"><aside class="rubric-question-preview">${preview?`<img src="/api/questions/${q.id}/template-crop" loading="lazy" decoding="async" alt="Blank exam question ${esc(q.key)}"><p class="help">Blank exam · page ${q.page}</p>`:'<p class="help">Save this question and its box in Exam outline to show its blank-exam preview.</p>'}</aside><div class="rubric-question-content"><details class="rubric-answer-summary"><summary>Answer key · ${reviewedSolution(q)?'Reviewed':'Still needed'}</summary><pre>${esc(reviewedSolution(q)||'Add and review the answer in the Answer keys step.')}</pre>${button('Edit answer','setup-answer-edit',`data-key="${esc(q.key)}"`)}</details><h4 class="rubric-content-title">Rubric</h4><label class="rubric-selection-rule">Selection rule<select data-field="selectionMode">${option('one','Select the ONE best grade',q.selectionMode)}${option('all','Select ALL applicable items',q.selectionMode)}</select></label><div class="rubric-items">${q.items.map((item,j)=>`<div class="rubric-item" data-item="${j}"><div class="rubric-choice-heading"><label>Label<input data-item-field="label" aria-label="Rubric label" value="${esc(item.label)}"></label><label>Points<input type="number" step="any" data-item-field="points" aria-label="Rubric points" value="${item.points}"></label>${button('×','remove-item',`data-question="${index}" data-item="${j}" aria-label="Remove rubric item"`)}</div><label class="rubric-description">Criterion<textarea data-item-field="description" aria-label="Rubric description">${esc(item.description)}</textarea></label></div>`).join('')||'<p class="help rubric-empty-items">Add a rubric item to begin.</p>'}</div><div class="row rubric-item-actions">${button('+ Add rubric item','add-item',`data-question="${index}"`)}</div><details class="rubric-question-settings"><summary>Question details &amp; box link</summary><label>Attach this rubric to an outlined question<select data-rubric-target="${index}">${S.questions.map(t=>option(t.key,t.key+' · '+t.title+(t.rect?' · box on page '+t.page:' · no box'),q.key)).join('')}</select></label><div class="row"><label class="short">Question label<input data-field="key" value="${esc(q.key)}" placeholder="7a"></label><label>Title<input data-field="title" value="${esc(q.title)}"></label><label class="short">Maximum points<input type="number" step="any" data-field="maxPoints" value="${q.maxPoints}"></label></div>${button('Remove question','remove-question',`data-question="${index}"`)}</details></div></div></section>`;
}

async function attachRubric(index,key){collectQuestions();const source=S.questions[index],target=S.questions.find(q=>q.key===key);if(!source||!target||source===target)return;if(target.items.length&&!await confirmAction('Replace the rubric for outlined question '+key+' with these items? The target box and version-specific guidance are retained.'))return;const merged={...source,response:target.response,id:target.id,key:target.key,title:target.title,page:target.page,rect:target.rect,guidance:target.guidance||source.guidance||'',checkedFiles:target.checkedFiles||[]};S.questions=S.questions.filter((q,i)=>i!==index).map(q=>q===target?merged:q);S.dirty=true;render();}
function collectQuestions(){for(const section of $$('.question')){const q=S.questions[Number(section.dataset.index)];window.GScopeResponses?.collect?.(section,q);for(const input of section.querySelectorAll('[data-field]'))q[input.dataset.field]=input.dataset.field==='maxPoints'?Number(input.value):input.value;for(const row of section.querySelectorAll('.rubric-item')){const item=q.items[Number(row.dataset.item)];for(const input of row.querySelectorAll('[data-item-field]'))item[input.dataset.itemField]=input.dataset.itemField==='points'?Number(input.value):input.value;}}for(const input of $$('[data-guidance-question]')){const q=S.questions.find(q=>q.key===input.dataset.guidanceQuestion);if(q)q.guidance=withNotes(q,input.value);}return S.questions;}
function cropsView(){
 const v=S.version,q=v.questions[S.cropQuestion]||v.questions[0],files=v.files.filter(f=>f.kind==='scans');
 const back=button('← Back to grade & review','tab','data-tab="process"');
 if(!q||!files.length||!v.booklets.length)return '<section class="card">'+back+'<p>Save question cards and confirm scan boundaries first.</p></section>';
 S.cropQuestion=v.questions.indexOf(q);S.cropFile=files.some(f=>f.id===S.cropFile)?S.cropFile:files[0].id;
 const booklets=v.booklets.filter(b=>b.file_id===S.cropFile);S.cropBooklet=booklets.some(b=>b.id===S.cropBooklet)?S.cropBooklet:booklets[0]?.id;S.cropPage=q.page;S.rect=q.rect;
 const control=(label,id,field,values,selected)=>{const i=values.findIndex(x=>x.id===selected);return `<div class="gs-crop-control"><label for="${id}">${label}</label><div class="gs-crop-stepper">${button('←','grading-crop-step',`data-field="${field}" data-offset="-1" aria-label="Previous ${label.toLowerCase()}" ${i<=0?'disabled':''}`)}<select id="${id}">${values.map(x=>option(x.id,x.text,selected)).join('')}</select>${button('→','grading-crop-step',`data-field="${field}" data-offset="1" aria-label="Next ${label.toLowerCase()}" ${i<0||i+1>=values.length?'disabled':''}`)}</div></div>`;};
 return `<section class="card"><div class="gs-crop-back">${back}</div><div class="gs-crop-controls">${control('Question','crop-question','question',v.questions.map((x,i)=>({id:String(i),text:x.key+' · '+x.title})),String(S.cropQuestion))}${control('Scan PDF','crop-file','file',files.map((f,i)=>({id:f.id,text:'PDF '+(i+1)+' · '+f.name})),S.cropFile)}${control('Sample exam','crop-booklet','booklet',booklets.map((b,i)=>({id:b.id,text:'Exam '+(i+1)+' · pages '+(b.start+1)+'–'+(b.start+b.pages)})),S.cropBooklet)}<div class="gs-crop-control gs-crop-page"><label for="crop-page">Question page</label><input id="crop-page" type="number" min="1" max="200" value="${q.page}"></div>${button('Show page','show-page')}</div><p class="help">Drag a box around the question and all its work. Exclude names, IDs and neighboring answers. This inspection is optional; grading uses the saved Exam outline boxes.</p><div class="crop-layout"><div class="page-wrap"><canvas id="crop-canvas" aria-label="Draw the anonymous question crop"></canvas></div><section><h3>Question crop</h3><div id="crop-coordinates" class="help"></div>${button('Save crop','save-crop','',true)}<div id="crop-preview" style="margin-top:12px">${q.rect?`<img class="crop-preview" src="/api/booklets/${S.cropBooklet}/crop/${q.id}" alt="Saved question crop">`:'<p class="help">Draw and save a crop first.</p>'}</div></section></div></section>`;
}
async function loadPage(){const request=S.cropImageRequest=(S.cropImageRequest||0)+1;const b=S.version.booklets.find(x=>x.id===S.cropBooklet);if(!b)return;S.cropPage=Number($('#crop-page').value);if(S.cropPage<1||S.cropPage>b.pages)throw new Error('Choose a page within this booklet.');const image=new Image();S.image=null;image.onload=()=>{if(request!==S.cropImageRequest||!$('#crop-canvas'))return;S.image=image;const c=$('#crop-canvas');c.width=image.naturalWidth;c.height=image.naturalHeight;drawCrop();};image.onerror=()=>message('The selected PDF page could not be rendered.');image.src=`/api/files/${b.file_id}/page/${b.start+S.cropPage-1}`;const c=$('#crop-canvas');let start=null;const point=e=>{const r=c.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))];};c.onpointerdown=e=>{if(!S.image)return;start=point(e);c.setPointerCapture(e.pointerId);};c.onpointermove=e=>{if(!start)return;const p=point(e);S.rect=[Math.min(start[0],p[0]),Math.min(start[1],p[1]),Math.max(start[0],p[0]),Math.max(start[1],p[1])];drawCrop();};c.onpointerup=()=>{start=null;};}
function drawCrop(){const c=$('#crop-canvas');if(!c||!S.image)return;const ctx=c.getContext('2d');ctx.drawImage(S.image,0,0);if(S.rect){const [x0,y0,x1,y1]=S.rect;ctx.fillStyle='#8951d025';ctx.strokeStyle='#8951d0';ctx.lineWidth=3;ctx.fillRect(x0*c.width,y0*c.height,(x1-x0)*c.width,(y1-y0)*c.height);ctx.strokeRect(x0*c.width,y0*c.height,(x1-x0)*c.width,(y1-y0)*c.height);$('#crop-coordinates').textContent=`Page ${S.cropPage} · region ${S.rect.map(x=>Math.round(x*100)+'%').join(', ')}`;}}
