function modelLabel(name){const n=String(name||''),size=/(\d+)b(?:[-:]|$)/i.exec(n),family=/qwen35|qwen3\.5/i.test(n)?'Qwen 3.5'+(size?' '+size[1]+'B':''):n;return 'G-Works Local - '+family+' ('+(S.boot?.localAIProvider==='openai-local'?'Local server':'Ollama')+')';}
