function runReviewView(){const r=S.run;return `<div class="toolbar g2-review-toolbar">${button('← Grade submissions','grading-back')}<label>Exam version<select id="review-version"><option value="">Choose an exam version</option>${projectOptions()}</select></label>${S.version?`<label>Run<select id="review-run"><option value="">Choose a run</option>${S.version.runs.map(x=>option(x.id,x.status+' · '+new Date(x.created).toLocaleString(),r?.id)).join('')}</select></label>`:''}</div>${r?`<section class="card"><div class="spread"><div><strong id="gs-grading-live-summary">${esc(GScopeGrading.summary(r))}</strong><span class="help"> · ${r.thinking?'Extended reasoning for free response':'Standard grading'}</span></div><div class="row">${['queued','running'].includes(r.status)?button('Pause after current request','pause-run',`data-id="${r.id}"`):''}${button('Review consistency','review-consistency',`data-id="${r.id}"`)}${['paused','error'].includes(r.status)?button('Abandon…','grading-abandon',`data-id="${r.id}"`):''}<span id="gs-export-current">${GScopeGrading.exportControl(S.version)}</span></div></div><progress max="${r.total||1}" value="${r.completed}"></progress>${r.error?`<p class="notice warning">${esc(r.error)}</p>`:''}<p class="help">Review suggested grades before exporting.</p></section>${S.consistencyReport?.runId===r.id?GScopeConsistency.reportView(S.consistencyReport):''}${GScopeGrading.abandonView()}${GScopeGrading.reviewNav(r)}<div class="review-grid"><section class="proposal-list">${GScopeGrading.reviewItems(r).map((p,i)=>{const q=r.questions.find(q=>q.id===p.question_id),b=r.booklets.findIndex(b=>b.id===p.booklet_id);return `<button data-action="proposal" data-id="${p.id}" class="${S.selected===p.id?'active':''}">Exam ${b+1} · ${esc(q?.key)} ${p.review?'✓':''}<small>${p.review?'Reviewed':p.result.needsReview?'Needs review':'AI proposal'}</small></button>`;}).join('')||'<p>Waiting for the first suggestion…</p>'}</section><section id="proposal-detail"></section></div>`:'<section class="card"><p>Select an assignment and run to review its suggestions.</p></section>'}`;}
function bindReview(){const choicesForQuestion=GScopeGrading.reviewItems(S.run);const p=choicesForQuestion.find(x=>x.id===S.selected)||choicesForQuestion[0];if(!p){$('#proposal-detail').innerHTML='<section class="card"><p>No assessments for this question in this run yet.</p></section>';return;}S.selected=p.id;const q=S.run.questions.find(x=>x.id===p.question_id),index=S.run.booklets.findIndex(x=>x.id===p.booklet_id),draft=S.reviewDrafts.get(p.id),choices=draft?.choices||p.review?.choices||p.result.items;$('#proposal-detail').innerHTML=`<section class="card"><h2>Exam ${index+1} · ${esc(q.key)} · ${esc(q.title)}</h2><img class="crop-preview review-work" src="/api/runs/${S.run.id}/proposals/${p.id}/crop" alt="Anonymous source answer crop"><p class="notice"><strong>Original assessment:</strong> ${esc(p.result.reason)}</p><p class="help">Uncertainty: ${esc(p.result.uncertainty||'None reported')}</p><p>${q.selectionMode==='one'?'Select one rubric item.':'Select every applicable rubric item.'}</p>${q.items.map(item=>`<label class="check"><input type="${q.selectionMode==='one'?'radio':'checkbox'}" name="review-choice" value="${item.id}" ${choices.includes(item.id)?'checked':''}><span><strong>${esc(item.label)} · ${item.points>0?'+':''}${item.points} points</strong><br>${esc(item.description)}</span></label>`).join('')}<label>Review note (optional)<textarea id="review-note">${esc(draft?.note??p.review?.note??'')}</textarea></label>${button('Save reviewed choice','review-proposal',`data-id="${p.id}"`,true)}<p class="help">This saves a local review. It does not apply a grade in Gradescope or change recorded grade history.</p><details><summary>Optional local grade-record reference</summary><label>System / database<input id="record-system" placeholder="Grades"></label><label>Record ID<input id="record-id" placeholder="Existing local enrollment or record ID"></label>${button('Save reference for this exam','record-link',`data-id="${p.booklet_id}"`)}<p class="help">References are scoped to this assignment course and semester. No existing grade database is changed or searched by name.</p></details></section>`;}
