async function acceptVersion(v){window.GScopeGrading?.invalidate?.(v.id);window.GScopeGradeWorkspace?.invalidate?.(v.id);window.GScopeOutline?.acceptVersion?.(v);S.version=v;S.questions=structuredClone(v.questions);S.dirty=false;await refreshProjects();render();}
async function openVersion(id,{keepStep=false,preserveGuidance=false}={}){const tab=S.tab,step=S.version?questionSetupStep():null,navigation=keepStep&&tab==='process'?window.GScopeGradeWorkspace?.navigation?.():null;if(!await leave({preserveGuidance}))return false;const next=await api('/api/versions/'+id);GScopeWorkflow.reset();S.tab=keepStep?tab:'materials';if(keepStep&&step){S.questionSetupSteps||={};S.questionSetupSteps[id]=step;}if(navigation)window.GScopeGradeWorkspace?.restoreNavigation?.(next,navigation);await acceptVersion(next);return true;}
