    if(S.normalization){const job=await api('/api/jobs/'+S.normalization.id);if(job.status==='done'){const request=S.normalization;S.normalization=null;const proposal={versionId:request.versionId,questions:job.result.questions};if(S.version?.id===request.versionId){collectQuestions();if(JSON.stringify(S.questions)!==request.questions||S.version.raw_rubric!==request.text||($('#raw-rubric')&&$('#raw-rubric').value!==request.text)){S.pendingNormalization=proposal;if(S.tab==='rubric'){const raw=$('#raw-rubric')?.value;render();if(raw!==undefined)$('#raw-rubric').value=raw;}message('Proposed cards are ready. Your edits were kept. Choose Load proposed cards only if you want to replace them.');}else applyNormalization(proposal);}else S.pendingNormalization=proposal;}else if(['error','cancelled'].includes(job.status)){S.normalization=null;forgetRubricJob();render();message(job.status==='cancelled'?'Rubric preparation stopped. Saved outlines and rubrics were kept.':job.error);}else if($('#normalization-status'))$('#normalization-status').textContent='The local model is preparing rubric proposals…';}
    if(S.run&&['queued','running'].includes(S.run.status)){const result=await api('/api/runs/'+S.run.id);if(result.completed!==S.run.completed||result.status!==S.run.status){S.run=result;S.consistencyReport=null;window.GScopeGradeWorkspace?.invalidate?.(result.version_id);if(!['queued','running'].includes(result.status)){window.GScopeGrading?.invalidate?.(result.version_id);refreshAssignmentProgress(true);}if(S.version)S.version=await api('/api/versions/'+S.version.id);if(S.view==='review'||(S.view==='projects'&&S.tab==='process'))render();}else{S.run=result;const summary=$('#gs-grading-live-summary');if(summary)summary.textContent=GScopeGrading.summary(result);}}
